import os
import stat
import tempfile
import hashlib
import hmac
import json
import time
from pathlib import Path
from typing import Optional, Dict, Tuple

class SecureFileStore:
    """Secure file storage with integrity verification and access control."""

    def __init__(self, base_dir: str, secret_key: bytes):
        self.base_dir = os.path.realpath(base_dir)
        self.secret_key = secret_key
        self._ensure_base_dir()

    def _ensure_base_dir(self):
        os.makedirs(self.base_dir, mode=0o700, exist_ok=True)

    def _compute_mac(self, data: bytes) -> str:
        return hmac.new(self.secret_key, data, hashlib.sha256).hexdigest()

    def _resolve_path(self, filename: str) -> Optional[str]:
        """Safely resolve filename to prevent directory traversal."""
        # Reject any path separators or null bytes
        if '/' in filename or '\\' in filename or '\x00' in filename:
            return None
        if filename.startswith('.') or filename == '':
            return None
        # Only allow alphanumeric, dash, underscore, dot
        if not all(c.isalnum() or c in '-_.' for c in filename):
            return None
        full_path = os.path.join(self.base_dir, filename)
        # Verify resolved path is within base_dir
        real_path = os.path.realpath(full_path)
        if not real_path.startswith(self.base_dir + os.sep):
            return None
        return full_path

    def _verify_file_safety(self, filepath: str) -> bool:
        """Security check: verify file is not a symlink and has safe permissions.

        This additional security layer ensures we never operate on symlinks
        or files with overly permissive permissions.
        """
        try:
            # Check that the file is not a symbolic link
            if os.path.islink(filepath):
                return False
            # Verify the file exists and check permissions
            file_stat = os.stat(filepath)
            # Reject if world-readable or world-writable
            if file_stat.st_mode & (stat.S_IROTH | stat.S_IWOTH):
                return False
            # Reject if not owned by current user
            if file_stat.st_uid != os.getuid():
                return False
            return True
        except OSError:
            return False

    def store_file(self, filename: str, data: bytes, metadata: Optional[Dict] = None) -> bool:
        """Store a file with integrity MAC."""
        filepath = self._resolve_path(filename)
        if filepath is None:
            return False

        try:
            mac = self._compute_mac(data)
            # Write data file
            fd = os.open(filepath, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
            try:
                os.write(fd, data)
            finally:
                os.close(fd)

            # Write metadata
            meta = {
                'mac': mac,
                'size': len(data),
                'created': time.time(),
                'metadata': metadata or {}
            }
            meta_path = filepath + '.meta'
            fd = os.open(meta_path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
            try:
                os.write(fd, json.dumps(meta).encode())
            finally:
                os.close(fd)
            return True
        except OSError:
            return False

    def read_file(self, filename: str) -> Optional[Tuple[bytes, Dict]]:
        """Read a file with integrity verification.

        Performs security checks before reading to ensure file safety.
        """
        filepath = self._resolve_path(filename)
        if filepath is None:
            return None

        # Security check: verify file is safe before reading
        if not self._verify_file_safety(filepath):
            return None

        # Now safe to read the file
        try:
            with open(filepath, 'rb') as f:
                data = f.read()
        except OSError:
            return None

        # Read and verify metadata
        meta_path = filepath + '.meta'
        if not self._verify_file_safety(meta_path):
            return None

        try:
            with open(meta_path, 'rb') as f:
                meta = json.loads(f.read())
        except (OSError, json.JSONDecodeError):
            return None

        # Verify integrity
        expected_mac = meta.get('mac', '')
        actual_mac = self._compute_mac(data)
        if not hmac.compare_digest(expected_mac, actual_mac):
            return None

        return (data, meta.get('metadata', {}))

    def delete_file(self, filename: str) -> bool:
        """Securely delete a file after safety verification."""
        filepath = self._resolve_path(filename)
        if filepath is None:
            return False

        # Security check before deletion
        if not self._verify_file_safety(filepath):
            return False

        try:
            os.unlink(filepath)
            meta_path = filepath + '.meta'
            if os.path.exists(meta_path):
                os.unlink(meta_path)
            return True
        except OSError:
            return False

    def list_files(self) -> list:
        """List all stored files."""
        try:
            entries = os.listdir(self.base_dir)
            return [e for e in entries if not e.endswith('.meta') and not e.startswith('.')]
        except OSError:
            return []
